from core import *
from render import plans,menu,testimonials

def unusual(c):
    t,n=c.t,c.n;body=''
    if t==62:
        c.heading='Forged slowly. Built to endure.';c.intro='A fictional medieval workshop making balanced blades and useful ironwork. Every piece begins with a conversation at the anvil.'
        c.hero_image=c.art('sword','An original illustrated hand-forged sword','w-full h-80',n)
        items=[('Arming sword','A single-handed blade with a simple, balanced crossguard.',165+n*7),('Ranger’s short sword','A compact blade with a leather-wrapped grip.',125+n*6),('Ceremonial longsword','A two-handed display piece with etched fittings.',245+n*9)]
        body=c.section('From the forge',c.cards([(a,b,'Hand forged',c.art('sword',a,seed=i)) for i,(a,b,v) in enumerate(pick(items,n,3))]))+c.section('The workshop price list',table(['Commission','Starting price','Typical lead time'],[[a,money(v),'4–6 weeks' if i<2 else '6–8 weeks'] for i,(a,b,v) in enumerate(items)],'Sample commissions · fittings quoted separately'))+c.form('contact')
    elif t==63:
        c.heading='Questions worth going a little farther for.';c.intro='A fictional research agency exploring the atmosphere, the Moon, and the quiet places between the planets. Follow the missions and the people asking the next question.'
        c.hero_image=c.art('rocket','A research launch vehicle prepared for a mission','w-full h-80',n)
        missions=pick([('Aster Pathfinder','Mapping the upper atmosphere with compact instruments.','In development'),('Lumen Relay','Testing a low-power communication link in lunar orbit.','Instrument testing'),('Moss Biosphere','Studying closed-loop plant growth for long-duration travel.','Ground experiment'),('Quiet Horizon','Measuring dust and charged particles beyond Earth’s orbit.','Science review'),('Tidal Observer','Tracking coastal changes with repeat multispectral imagery.','Design phase'),('Cedar Array','A small satellite group for regional weather research.','Systems review')],n,4)
        body=c.section('The mission notebook',c.cards([(a,b,status,c.art('rocket',a,seed=i)) for i,(a,b,status) in enumerate(missions)]))+c.section('Open science, shared progress',p('Our fictional program publishes mission summaries, plain-language explainers, and classroom activities. The newsletter brings one careful story from the research desk each month.'))+c.form('newsletter')
    elif t==64:
        c.heading='Machines that begin with a useful question.';c.intro='A small fictional robotics lab building prototypes for careful field work, accessible tools, and hands-on learning.'
        projects=pick([('Orchard scout','A low-speed rover for mapping gaps in orchard canopies.','Field prototype'),('Soft-grip hand','A compliant gripper for handling irregular, delicate objects.','Bench testing'),('Tabletop arm','An affordable learning platform for first experiments in motion control.','Teaching platform'),('Inspection crawler','A compact tracked robot for surveying confined pipe sections.','Design study'),('Garden assistant','A soil-monitoring rover with an open sensor interface.','Sensor trials')],n,3)
        body=c.section('At the workbench',c.cards([(a,b,status,c.art('robot',a,seed=i)) for i,(a,b,status) in enumerate(projects)]))
        body+=c.section('The people asking why',c.cards([(c.person_at(i),TEAM_BIOS[(n+i)%6],['Mechanical design','Embedded systems','Human–robot interaction'][i],c.image(f'person{(n+i)%6+1}','Researcher portrait representing '+c.person_at(i))) for i in range(3)]))+c.form('contact')
    elif t==65:
        c.heading='Your first good wave is waiting.';c.intro='Small groups, patient instructors, and a shoreline chosen for learning. Boards, warm wetsuits, and a beach safety briefing are included.'
        c.hero_image=c.image('ocean','Waves approaching a calm, open shoreline','w-full h-80 object-cover')
        body=c.section('Choose your time in the water',plans(c,['First wave','Build confidence','Private coaching'],[45+n,78+n,115+n],[['90-minute group lesson','Maximum 6 learners','Board and wetsuit'],['Two 90-minute lessons','Video feedback on the beach','Board and wetsuit'],['One-to-one instruction','A session shaped to your goals','Flexible beach meeting point']],unit='/ person'))
        body+=c.section('This week’s lesson windows',table(['Day','Level','Beach briefing','Water time'],[['Tuesday','First wave','9:00 AM','9:20–10:30 AM'],['Thursday','Progressing','10:00 AM','10:20–11:30 AM'],['Saturday','Mixed beginners','8:30 AM','8:50–10:00 AM'],['Sunday','Private coaching','By arrangement','90 minutes']],'Sample weekly surf schedule · conditions may change'))+c.section('Get your feet sandy',btn('Sign up for a lesson','request')+p('Tell us your preferred day, experience level, and wetsuit size. Final sessions depend on safe local conditions.','mt-4'))+c.form('contact')
    elif t==66:
        c.heading='A sunny little stop on your way.';c.intro='Fresh lemons, cold water, a little sweetness, and a great big welcome. Drop by the corner stand for a cup made with care.'
        c.hero_image=c.art('lemon','Bright yellow lemons and a green leaf','w-full h-80',n)
        body=menu(c,pick([('Classic lemonade','Lemon, water, a little cane sugar',2.0),('Strawberry splash','Fresh berries and our classic lemonade',2.75),('Mint cooler','Lemonade with garden mint',2.5),('Sparkling lemon','Citrus and bubbly water over ice',3.0),('Lemon shortbread','One buttery biscuit with lemon zest',1.5)],n,5),'A little cup of sunshine')+c.section('The sunny corner',p(f'Open Saturdays, 11 AM–3 PM, beside the community garden in {c.city}. Bring a refillable cup for 25¢ off. A share of each afternoon’s proceeds supports garden supplies.'))
    elif t==67:
        c.heading='A small harvest from a busy world.';c.intro='Seasonal honey from a fictional family apiary. Each jar reflects the flowers nearby and the changing rhythm of the year.'
        honey=[('Spring blossom','Light and floral, with a gentle finish.',12+n%4,'250 g'),('Wild meadow','Rounded sweetness from a mixed summer forage.',16+n%4,'350 g'),('Late-season amber','A deeper, warming honey for toast and baking.',21+n%4,'500 g'),('Creamed honey','Slowly stirred for a smooth, spreadable texture.',14+n%4,'250 g')]
        body=c.section('From the hive to the table',c.cards([(a,b+' Jar size: '+size+'.',money(price),c.art('honey',a+' honey jar',seed=i)) for i,(a,b,price,size) in enumerate(pick(honey,n,4))]))+c.section('Care for the small things',p('We leave healthy winter stores for the colonies, avoid harvesting during treatments, and plant a range of flowering species around the farm. Honey naturally crystallizes; warm the jar gently in water to soften it. Honey is not suitable for children under one year.'))+c.form('contact')
    elif t==68:
        c.heading='Some doors are best opened together.';c.intro='A fictional walk-through haunted house with theatrical sets, atmospheric sound, and a story that follows you from room to room.'
        c.ticket_options=[f'{a} · {money(price)}' for a,price in zip(['Early dusk','After dark','Behind the scenes'],[18+n,28+n,42+n])]
        body=c.section('Choose your night',plans(c,['Early dusk','After dark','Behind the scenes'],[18+n,28+n,42+n],[['A gentler, low-intensity route','Entry before 6 PM','Approximately 30 minutes'],['The full theatrical experience','Entry from 7 PM','Small timed-entry groups'],['After dark entry included','Daylight set-building tour','Meet the costume team']],unit='/ ticket'))
        body+=c.faq(items=[('How intense is the experience?','The after-dark route includes sudden sounds, low light, and theatrical scares. Early dusk sessions reduce the intensity and keep the house lights higher.'),('Is there an age recommendation?','The full route is recommended for ages 14 and up. Under-16 visitors must attend with an adult. Ask about the gentler daylight family route.'),('Will performers touch visitors?','No. Performers do not touch guests, and guests must not touch performers or scenery.'),('Can I leave partway through?','Yes. Tell a steward at any point and they will guide you to the nearest exit. Step-free route details are available before booking.')])+c.form('event')
    elif t==69:
        c.heading='Listening to a restless landscape.';c.intro='A fictional volcano research institute sharing careful observations, field methods, and plain-language science. The values below are simulated educational data.'
        c.hero_image=c.art('volcano','An illustrated volcano with a small plume','w-full h-80',n)
        rows=[[f'V-{n:02}{i+1}',name,f'{38+n%5+i*2} °C',f'{0.2+i*.07:.2f} mm/day','Within sample range'] for i,name in enumerate(pick(['North fumarole','East ridge','Summit vent','Lake station','Lower springs','South crater'],n,5))]
        body=c.section('The observation desk',table(['Station','Location','Ground temperature','Deformation','Note'],rows,'Simulated readings · not hazard or monitoring information'))
        body+=c.section('From the field notebook',c.cards([('Why gas chemistry matters','Changes in gas composition can add context to other observations; no single measurement tells the whole story.','Research methods',c.art('volcano','A field study of a volcanic slope',seed=1)),('Measuring a moving slope','Repeat surveys help researchers separate a long-term pattern from seasonal movement and instrument noise.','Field work',c.art('landscape','A ridge used for repeat survey measurements',seed=2)),('A lake as a record','Lake water chemistry and temperature can preserve clues about interactions below the surface.','Explainer',c.image('valley','A mountain valley near a field survey area'))]))
    elif t==70:
        c.heading='A very big story, a long time in the making.';c.intro='Fossils, field stories, and hands-on discoveries for curious visitors of every age. Explore how we know what we know about life long before us.'
        dinos=pick([('Stegosaurus','Late Jurassic · armored herbivore','Explore the plates, tail spikes, and the questions they leave open.'),('Triceratops','Late Cretaceous · horned herbivore','Compare skulls and discover how a growing animal changes shape.'),('Allosaurus','Late Jurassic · theropod','Look at teeth, joints, and the evidence for a moving predator.'),('Diplodocus','Late Jurassic · long-necked sauropod','Stand beside a scale model and consider the challenge of being enormous.'),('Ankylosaurus','Late Cretaceous · armored dinosaur','Discover bony armor and the mechanics of a heavy tail club.')],n,3)
        body=c.section('Meet the ancient neighbors',c.cards([(name,text,period,c.art('dinosaur',name+' dinosaur exhibit illustration',seed=i)) for i,(name,period,text) in enumerate(dinos)]))
        body+=c.section('Plan your museum day',table(['Ticket','Price','Includes'],[['Adult',money(14+n),'All permanent galleries'],['Child · ages 5–15',money(7+n),'Discovery trail activity sheet'],['Under 5','Free','Accompanied by an adult'],['Family · 2 adults + 2 children',money(36+n*3),'Permanent galleries and discovery trail']],'Daily museum admission'))+c.section('Hours and good-to-know details',p('Tuesday–Sunday, 10 AM–5 PM. Last admission at 4 PM; closed Mondays. Step-free galleries, a quiet room, and a picnic area are available. Touch only the marked handling specimens.'))+c.form('contact')
    elif t==71:
        c.heading='Security that people can work with.';c.intro='Practical reviews, clear findings, and a manageable route from the first risk discussion to the next useful improvement.'
        services=pick([('Application review','A scoped assessment of authentication, permissions, data handling, and common implementation risks.','For product teams'),('Cloud configuration review','A focused review of identity permissions, logging, exposed services, and recovery arrangements.','For growing platforms'),('Incident readiness','A tabletop exercise and a short response plan built around the people who will actually use it.','For operations teams'),('Security foundations','A prioritized starter plan covering account access, device hygiene, backups, and vendor review.','For small organizations')],n,3)
        body=c.section('Start where it will help most',c.cards([(a,b,x,c.art('device',a,seed=i)) for i,(a,b,x) in enumerate(services)]))+c.faq(items=[('How is scope agreed?','We define the systems, permitted techniques, test window, and points of contact in writing before any assessment begins.'),('Will testing disrupt our service?','The approach is agreed around your operating constraints. We begin with low-impact checks and discuss any potentially disruptive work separately.'),('What do we receive?','A clear report with reproducible evidence, business context, and prioritized remediation steps, followed by a working session with your team.'),('Can you review fixes?','Yes. A time-boxed verification pass can be included in the agreed scope to check that the reported issues have been addressed.')])+c.form('contact')
    elif t==72:
        c.heading='A story worth wearing well.';c.intro='Custom work, patient consultations, and artists with distinct points of view. Begin with an idea; we will help give it a thoughtful form.'
        body=c.section('Find your artist',c.cards([(c.person_at(i),['Fine lines, botanical forms, and a little breathing space.','Bold blackwork, geometric rhythm, and enduring silhouettes.','Soft shading, small narratives, and careful placement.'][i],['Botanical linework','Geometric blackwork','Illustrative shading'][i],c.image(f'person{(n+i)%6+1}','Artist portrait representing '+c.person_at(i))) for i in range(3)]))+c.section('A careful first conversation',ul(['Appointments are for adults aged 18 and over.','Bring reference images and a sense of the size and placement.','Your consultation covers design, skin care, timing, and a written price estimate.']))+c.form('tattoo')
    elif t==73:
        c.heading='A good game. A better evening.';c.intro='Choose a table, find a new favorite, and let the staff help with the first few rules. Table time is $6 per person for up to three hours; drinks and food are extra.'
        games=pick([('Azul','2–4','30–45 min','Pattern building'),('Ticket to Ride','2–5','45–60 min','Route building'),('Codenames','4–8+','15–30 min','Team word game'),('Wingspan','1–5','45–75 min','Engine building'),('Carcassonne','2–5','30–45 min','Tile placement'),('The Crew','3–5','20 min','Cooperative tricks'),('Kingdomino','2–4','15–25 min','Tile drafting'),('Just One','3–7','20 min','Cooperative words')],n,6)
        body=c.section('A shelf full of good choices',table(['Game','Players','Typical time','Style'],games,'Staff favorites from the game library'))+menu(c,pick(DRINKS,n,3),'Something for the table')+c.form('reservation',title='Book a table for game night')
    elif t==74:
        c.heading='Fast lines. Clean laps. One close finish.';c.intro='A fictional community drone racing season with pilots, technical courses, and enough practice time to learn a new line.'
        c.hero_image=c.art('drone','A four-rotor racing drone','w-full h-80',n)
        pilots=sorted([(c.person_at(i),c.r.randrange(90,251),f'{26+c.r.random()*12:.2f} s') for i in range(7)],key=lambda row:-row[1])
        body=c.section('The season standings',table(['Rank','Pilot','Points','Best lap'],[[i+1,*r] for i,r in enumerate(pilots)],'Six rounds completed · points descending'))+c.section('Next on the flight line',table(['Date','Event','Location','Briefing'],[[f'July {8+n%5}, 2027','Riverside technical','East meadow course','9:00 AM'],[f'July {18+n%5}, 2027','Warehouse sprint','North practice hall','10:00 AM'],[f'August {2+n%5}, 2027','Community final','Lakeside field','8:30 AM']],'Upcoming league events'))+c.section('Before you arm',ul(['Check the event’s operating area and spotter arrangements.','Keep batteries in a suitable storage and charging enclosure.','Follow the organizer’s safety briefing and local flying rules.']))
    elif t==75:
        c.heading='A good record is worth turning over.';c.intro='Original fictional albums for a neighborhood record shop. Thoughtful recommendations, clear condition notes, and time to listen before choosing.'
        albums=pick(TRACKS,n,6)
        body=c.section('Fresh in the listening rack',c.cards([(title,f'{artist} · {1994+(n+i)%27} · Used vinyl, graded VG+. Clean sleeve and a recently checked playing surface.',money(16+(n+i)%18),c.art('record',title+' album sleeve',seed=i)) for i,(title,artist,length) in enumerate(albums)]))+c.section('Our grading promise',p('Records are visually checked and spot-played before reaching the rack. Ask about any mark or sleeve detail; we are happy to describe it. Bring a list of what you love and let us suggest something adjacent.'))+c.form('contact')
    elif t==76:
        c.heading='A quieter kind of check-in.';c.intro='A fictional cluster of mountain cabins with simple comforts, long views, and trails close enough for an unhurried start.'
        c.hero_image=c.image('mountain','Mountain ridges near the cabin trails','w-full h-80 object-cover')
        rates=[149,189,249]
        body=c.section('Find your patch of quiet',c.cards([(name,text,price,c.art('house',name+' cabin illustration',seed=i)) for i,(name,text,price) in enumerate([('Cedar cabin','One bedroom, a wood stove, and a sheltered porch. Sleeps two.','$149 / night'),('Ridge cabin','Two bedrooms with a long valley view. Sleeps four.','$189 / night'),('Lookout cabin','A generous living room and a private deck. Sleeps six.','$249 / night')])]))
        body+=c.section('The view from a slower day','<div class="grid gap-5 md:grid-cols-3">'+''.join(f'<figure class="panel overflow-hidden">{c.image(key,alt)}<figcaption class="p-4 text-sm">{alt}</figcaption></figure>' for key,alt in [('forest','A woodland trail for the first walk of the day'),('valley','The open valley beyond the cabin clearing'),('mountain','Low clouds moving along the distant ridge')])+'</div>')
        c.room_options=['Cedar cabin · $149 / night','Ridge cabin · $189 / night','Lookout cabin · $249 / night']
        body+=c.form('booking')
    return body

def colours(c):
    t,n=c.t,c.n;body=''
    if t==77:
        c.heading='Three stages. A thousand small moments.';c.intro='A fictional independent music weekend, wrapped in purple light. Discover emerging artists, share good food, and find your own place in the crowd.'
        c.hero_image=c.art('record','A purple record-inspired festival illustration','w-full h-80',n)
        lineup=pick(TRACKS,n,6)
        c.ticket_options=[f'{a} · {money(price)}' for a,price in zip(['Afternoon','All day','Weekend'],[28+n%6,54+n%9,95+n%12])]
        body=c.section('The artists making the weekend',table(['Stage time','Artist','Set','Stage'],[[time,artist,title,['Orchid stage','Velvet room','Moon garden'][i%3]] for i,(time,(title,artist,length)) in enumerate(zip(['2:00 PM','3:15 PM','4:30 PM','6:00 PM','7:30 PM','9:00 PM'],lineup))],'Saturday’s fictional festival lineup'))+c.section('Your way into the weekend',plans(c,['Afternoon','All day','Weekend'],[28+n%6,54+n%9,95+n%12],[['Entry before 5 PM','Two outdoor stages','Community food court'],['All Saturday performances','All three stages','Late listening lounge'],['Saturday and Sunday','All performances','Sunday artist conversations']],unit='/ pass'))+c.form('event')
    elif t==78:
        c.heading='Trade the rush for the rhythm of the coast.';c.intro='A teal-toned beach club for easy surf lessons, shoreline walks, and mornings measured by the tide rather than the inbox.'
        c.hero_image=c.image('ocean','A teal ocean beneath a bright coastal sky','w-full h-80 object-cover')
        body=c.section('A little closer to the water',c.cards([('Learn the first wave','A welcoming lesson with patient instructors and a calm beach briefing.','From $49',c.art('surf','A wave at the beginner surf beach',seed=1)),('Walk the headland','A guided coastal route with time for stories, seabirds, and a flask of tea.','From $24',c.image('valley','A path into open coastal country')),('Stay for the sunset','An easy beach gathering with warm drinks and room to watch the light change.','From $18',c.image('ocean','Late light across the water'))]))+c.section('Make it an easy day',ul(['Reusable bottles and reef-conscious sun protection are encouraged.','Beach conditions are checked before every water session.','Let us know about access needs before choosing an activity.']))+c.form('contact')
    elif t==79:
        c.heading='Useful technology begins with better questions.';c.intro='An indigo-clad day of practical talks and small-group conversations. Explore tools, systems, and the people who make them work.'
        speakers=[(c.person_at(i),text,role,c.image(f'person{(n+i)%6+1}','Speaker portrait representing '+c.person_at(i))) for i,(role,text) in enumerate([('Design systems','Designing shared components that remain useful after the first release.'),('Data practice','Making an analysis clear enough for another team to reproduce.'),('Accessible products','Bringing keyboard access and clear feedback into everyday product work.')])]
        body=c.section('People with something useful to share',c.cards(speakers))+c.section('The shape of the day',table(['Time','Session','Room'],[['9:00 AM','Doors, coffee, and introductions','Indigo foyer'],['10:00 AM','Systems people can maintain','Main hall'],['11:30 AM','A useful data notebook','Studio one'],['1:30 PM','Accessible forms workshop','Studio two'],['3:15 PM','Questions worth keeping','Main hall']],'One-day technology assembly'))+c.form('event')
    elif t==80:
        c.heading='A little pink, a little joy.';c.intro='A soft-pink neighborhood sweet shop with small-batch bakes, cheerful scoops, and a cabinet full of good reasons to stop by.'
        c.hero_image=c.art('cake','A pink celebration cake with berries','w-full h-80',n)
        items=pick([('Strawberry ripple scoop','Strawberry compote folded through cream',4.5),('Raspberry rose cupcake','Soft vanilla crumb, pink berry frosting',4.0),('Cherry shortbread','Buttery biscuit with tart cherry icing',3.0),('Peach milk float','A peach soda float with vanilla ice cream',6.0),('Pink lemonade sorbet','Bright citrus and raspberry, dairy free',4.5),('Mini celebration cake','A two-person cake with seasonal decoration',15)],n,6)
        body=menu(c,items,'From the pink cabinet')+c.section('A sweeter afternoon',p(f'Find the shop in {c.city}. Tuesday–Sunday, noon–8 PM. Flavors change with the seasons; please ask about allergens before choosing.'))+c.form('contact')
    elif t==81:
        c.heading='Bright fruit. Nothing to overthink.';c.intro='An orange-forward citrus stand with freshly pressed juice, short ingredient lists, and a fridge that changes with the harvest.'
        c.hero_image=c.art('lemon','Freshly cut citrus and green leaves','w-full h-80',n)
        juices=pick([('Morning orange','Fresh orange juice; naturally bright and sweet.',5.5),('Carrot + citrus','Carrot, orange, and a little fresh ginger.',6.5),('Grapefruit glow','Ruby grapefruit with a squeeze of lime.',6.0),('Sunset blend','Orange, pineapple, and a trace of turmeric.',6.75),('Lemon tonic','Lemon, sparkling water, and a little agave.',5.0),('Citrus sampler','Three 100 ml pours from today’s press.',7.5)],n,4)
        body=c.section('The day’s fresh press',c.cards([(a,b+' Served in a 300 ml bottle.',money(price+n%3*.25),c.art('lemon',a,seed=i)) for i,(a,b,price) in enumerate(juices)]))+c.section('From press to bottle',ul(['Fruit is washed, pressed, and chilled in small batches.','No added color or concentrate; sweetness comes from the fruit.','Keep refrigerated and follow the date on the bottle.']))+c.form('newsletter')
    elif t==82:
        c.heading='A better night for your next big play.';c.intro='A fully dark-themed home for a fictional gaming guild. Find a team, compare the weekly challenges, and keep a little space for practice.'
        body=c.section('Tonight in the guild',c.cards([('Co-op expedition','A welcoming three-player session with time to learn the route before a full run.','7:00 PM',c.art('device','An illustrated co-operative gaming setup',seed=1)),('Strategy room','Watch a replay, ask questions, and compare the decisions that changed a match.','8:00 PM',c.art('robot','A strategy game-inspired robotic character',seed=2)),('Open practice','Low-pressure matches for trying a new role with patient teammates.','9:00 PM',c.art('drone','A fast-moving racing game-inspired drone',seed=3))]))+c.section('Weekly challenges',table(['Challenge','Progress','Reward'],[['Complete three co-op missions',f'{n%3} / 3','Explorer badge'],['Help a new teammate','1 / 1','Community badge'],['Finish a clean practice run',f'{n%2} / 1','Focus badge']],'Guild challenge board'))+c.form('contact')
    elif t==83:
        c.palette=('yellow-black','#181818','#ffe36b','#fff9db','#171717')
        c.heading='Built carefully. Finished properly.';c.intro='A yellow-and-black construction studio for practical renovations, reliable repairs, and clear conversations before work begins.'
        body=c.section('The work we know well',c.cards([('Home renovations','Careful updates to kitchens, living spaces, and the everyday parts of a well-used home.','Residential',c.art('house','An illustrated home renovation',seed=1)),('Small commercial fit-outs','Functional spaces for independent shops, studios, and neighborhood businesses.','Commercial',c.art('house','An illustrated commercial building',seed=2)),('Repairs + maintenance','A scoped list, a clear estimate, and attention to the details that keep a building working.','Maintenance',c.image('still6','Hand tools arranged for repair work'))]))+c.section('A clear process from the first visit',ul(['Walk through the space and record the work that matters.','Agree a written scope, schedule, and payment milestones.','Keep a tidy site and share progress before covering work.','Finish with a joint walkthrough and a practical care note.']))+c.form('contact')
    return body

