def multi(c):
    t,n=c.t,c.n;body=''
    if t==84:
        vertical,unit,intro,features=SAAS[(n-1)%len(SAAS)]
        c.heading=f'Give {vertical} a little more clarity.';c.intro=intro+' A useful shared space for the next stage of your work.'
        c.hero_image=c.art('device','A calm, organized workspace dashboard','w-full h-80',n)
        descriptions=['Keep the next action visible without another meeting.','Bring the right context into the place where decisions happen.','Review progress and make the handoff clear for the next person.','A simple structure that leaves room for the way your team works.','Find the details you need without searching through old messages.','Make time for the work, with less effort spent arranging it.']
        body=c.section('Useful from the first day',c.cards([(feature,descriptions[(i+n)%6],'Made for your team',c.art('device',feature,seed=i)) for i,feature in enumerate(features)]),id='features')+testimonials(c)
        prices=[12+n%8,32+n%12,89+n%16]
        body+=c.section('A straightforward monthly plan',plans(c,['Begin','Build','Expand'],prices,[[f'3 active {unit}s','Two team members','Email support'],[f'25 active {unit}s','Ten team members','Priority support'],[f'Unlimited {unit}s','Unlimited members','Dedicated onboarding']]),id='pricing')+c.faq()+c.form('contact')
    elif t==85:
        c.heading='Good food. A table with your name on it.';c.intro='A neighborhood restaurant built around seasonal ingredients, generous conversation, and the pleasure of a meal that has not been rushed.'
        c.hero_image=c.image('cafe','A welcoming neighborhood dining room','w-full h-80 object-cover')
        body=menu(c,DINNERS[(n-1)%4],'From the seasonal kitchen')+menu(c,pick(DRINKS,n,3),'Something to sip')
        body+=c.section('A look around the table','<div class="grid gap-5 md:grid-cols-3">'+''.join(f'<figure class="panel overflow-hidden">{c.image(key,alt)}<figcaption class="p-4 text-sm">{alt}</figcaption></figure>' for key,alt in [('cafe','A warm corner of the dining room'),('pastry','A little something from the pastry kitchen'),('drinks','A drink prepared with care')])+'</div>')+testimonials(c,'Good evenings, remembered')+c.form('reservation')
    elif t==86:
        c.heading='A thoughtful base for a slower stay.';c.intro=f'A small fictional hotel in {c.city}, with restful rooms, a generous breakfast, and a team happy to point you toward a good local walk.'
        c.hero_image=c.image('valley','A quiet valley within reach of the hotel','w-full h-80 object-cover')
        rates=[129+n*3,169+n*3,229+n*3];rooms=[('Garden queen','A queen bed, soft linen, and a quiet courtyard outlook.'),('Corner king','A king bed, generous daylight, and a comfortable reading chair.'),('Terrace suite','A separate sitting area and a private space to greet the morning.')]
        c.room_options=[f'{a} · {money(rate)} / night' for (a,b),rate in zip(rooms,rates)]
        body=c.section('Find your kind of room',c.cards([(a,b,f'{money(rates[i])} / night',c.art('room',a+' hotel room illustration',seed=i)) for i,(a,b) in enumerate(rooms)]),id='rooms')+c.section('Small comforts, well considered',c.cards([('Breakfast, unhurried','Fresh bread, warm dishes, fruit, and good coffee from 7–10 AM.','Included',None),('A place to unwind','A quiet lounge with books, board games, and a fire on cool evenings.','Guest lounge',None),('Closer to the neighborhood','Walking notes, local recommendations, and a place to store your bicycle.','Local knowledge',None)]),id='amenities')+testimonials(c,'Notes from a good stay')+c.form('booking')
    elif t==87:
        c.heading='A neighborhood is stronger when more people belong.';c.intro='A fictional community charity helping residents share practical skills, find useful support, and turn small acts of care into lasting connections.'
        body=c.section('A simple mission, shared locally',p('We bring neighbors together through repair sessions, shared meals, and practical learning. The aim is not to do everything for everyone; it is to make the next useful connection easier to find.'),id='mission')
        body+=c.section('What a year of showing up can do',f'<div class="grid gap-5 md:grid-cols-3">{metric("Shared meals",f"{480+n*12:,}","Illustrative annual program total")}{metric("Volunteer hours",f"{1250+n*25:,}","Time contributed by neighbors")}{metric("Repair sessions",str(24+n),"Useful objects given another chapter")}</div>',id='impact')
        stories=[('A kettle, a conversation, a new friend','A Saturday repair session became a regular meeting place for two neighbors who had lived on the same street for years.','Repair together',c.image('still6','Simple tools used at a community repair table')),('More than a shared lunch','A volunteer cook brought a family recipe. The next month, three other families brought stories and dishes of their own.','Community table',c.image('cafe','A welcoming place for a shared community meal')),('A first step back into learning','An introductory workshop helped a returning learner find the confidence to join a longer course.','Practical learning',c.image('code','A laptop used for a practical learning session'))]
        body+=c.section('The people behind the numbers',c.cards(pick(stories,n,3)),id='stories')
        body+=c.section('A small gift, a practical possibility',c.cards([('A shared table','Help cover ingredients for a welcoming community lunch.','$25',None),('A useful first lesson','Contribute materials for a beginner repair or learning session.','$60',None),('Room for more neighbors','Support the space, tools, and access arrangements that bring a group together.','$120',None)]),id='giving')+c.form('donate')
    elif t==88:
        c.heading='Curious minds need room to grow.';c.intro='A fictional community school balancing strong foundations, creative exploration, and the confidence to ask a good question.'
        programs=pick([('Science in the field','Study local habitats, gather careful observations, and learn how evidence supports an explanation.','Ages 10–14'),('The maker studio','Work safely with familiar materials and turn a sketch into a useful, well-made object.','Ages 8–12'),('Stories and languages','Read widely, listen closely, and find a confident voice through conversation and writing.','Ages 7–14'),('Music together','Build rhythm, listening skills, and the joy of making something as an ensemble.','Ages 8–14'),('Mathematical thinking','Explore patterns, test a strategy, and explain the steps that make an answer work.','Ages 9–14')],n,3)
        body=c.section('A balanced way to learn',c.cards([(a,b,age,c.art('device' if i%2 else 'landscape',a,seed=i)) for i,(a,b,age) in enumerate(programs)]),id='programs')
        body+=c.section('Dates for the family calendar',table(['Date','Event','Time','Place'],[[f'September {6+n%5}, 2027','Family welcome afternoon','3:30–5:00 PM','School garden'],[f'September {17+n%5}, 2027','Learning showcase','4:00–6:00 PM','Main hall'],[f'October {4+n%5}, 2027','Community field day','10:00 AM–1:00 PM','Playing field']],'Upcoming school events'),id='events')
        body+=c.section('The people beside the learning',c.cards([(c.person_at(i),TEAM_BIOS[(n+i)%6],['Head of school','Science coordinator','Creative learning lead'][i],c.image(f'person{(n+i)%6+1}','Staff portrait representing '+c.person_at(i))) for i in range(3)]),id='staff')+c.form('contact')
    elif t==89:
        c.heading=f'I’m {c.person.split()[0]}. I make useful things feel clear.';c.intro=f'An independent designer based in {c.city}, working across research, thoughtful interfaces, and the small details that help people get started.'
        c.hero_image=c.image(f'person{n%6+1}','Designer portrait representing '+c.person,'w-full h-80 object-cover')
        body=c.section('A little about the way I work',p('I begin by listening: to the people using a service, the team maintaining it, and the questions that keep turning up. Then I make the next step visible through sketches, prototypes, and clear words.'),id='about')+c.section('The tools behind the work',ul(pick(['User interviews and practical research plans','Information architecture and content structure','Responsive interface design with HTML and CSS','Accessible forms and keyboard navigation','Interactive prototypes and usability sessions','Design systems and component documentation','Clear product writing and helpful error messages','Cross-team workshops and thoughtful handoffs'],n,6)),id='skills')
        projects=pick([('A calmer booking flow','A clearer route from choosing dates to reviewing a reservation.','Service design'),('The neighborhood repair map','A simple directory helping residents find people who can mend everyday things.','Community tools'),('A useful learning dashboard','A study space that keeps the next lesson and the learner’s progress close together.','Product design'),('A field journal for everyone','A responsive editorial system for long reads and short observations.','Editorial design'),('Library membership, simplified','A welcoming sign-up with fewer decisions and better explanations.','Accessible forms')],n,3)
        body+=c.section('A few recent chapters',c.cards([(a,b,kind,c.art('device',a,seed=i)) for i,(a,b,kind) in enumerate(projects)]),id='projects')+testimonials(c,'What collaboration felt like')+c.form('contact')
    return body
